options.styles:
.routing { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.routing .title { font-size: 18px; font-weight: 600; }
.routing .chip { font-size: 12px; padding: 3px 9px; border-radius: 999px; border: 1px solid rgba(127,127,127,0.5); opacity: 0.85; white-space: nowrap; }
.routing .chip.off { border-color: #d97706; color: #d97706; opacity: 1; }
.routing .chip.on { border-color: #2f9e44; color: #2f9e44; opacity: 1; }
.routing .asof { font-size: 12px; opacity: 0.7; margin-left: auto; }
@media (max-width: 520px) { .routing .asof { display: none; } .routing .chip { font-size: 11px; padding: 2px 7px; } }

.section { font-size: 13px; width: 100%; }
.sub { font-size: 12px; opacity: 0.7; margin: 0 0 8px; }
table { width: 100%; border-collapse: collapse; font-size: 13px; }
th { font-size: 11px; font-weight: 500; text-transform: uppercase; letter-spacing: .04em; opacity: 0.7; text-align: left; padding: 4px 8px; border-bottom: 1px solid rgba(127,127,127,0.35); }
td { padding: 7px 8px; border-bottom: 1px solid rgba(127,127,127,0.25); vertical-align: middle; }
tr.dim td { opacity: 0.5; }
.rank { width: 22px; opacity: 0.7; font-variant-numeric: tabular-nums; }
.role { width: 64px; }
.name { font-weight: 600; }
.prov { font-size: 12px; opacity: 0.7; }
.cap { width: 34%; }
.barrow { display: flex; align-items: center; gap: 8px; }
.bar { position: relative; flex: 1; height: 8px; min-width: 60px; }
.track { position: absolute; left: 0; top: 0; right: 0; bottom: 0; border-radius: 4px; background: rgba(127,127,127,0.28); overflow: hidden; }
.fill { height: 100%; border-radius: 4px; background: #3b82f6; }
.fill.warning { background: #d97706; }
.fill.destructive { background: #dc2626; }
.mark { position: absolute; top: -3px; bottom: -3px; width: 2px; margin-left: -1px; background: #e5e7eb; }
.pct { width: 42px; text-align: right; font-variant-numeric: tabular-nums; }
.unk { opacity: 0.75; font-style: italic; }
.pace { white-space: nowrap; font-variant-numeric: tabular-nums; }
.pace .ok { color: #2f9e44; }
.pace .bad { color: #e8590c; }
.pace .out { color: #e03131; }
.pace .na { opacity: 0.7; }
.score { white-space: nowrap; font-variant-numeric: tabular-nums; }
.tag { font-size: 11px; padding: 1px 6px; border-radius: 4px; background: rgba(127,127,127,0.22); margin-left: 6px; white-space: nowrap; }
.why { font-size: 12px; opacity: 0.7; }
.narrow { display: none; }
@media (max-width: 520px) { .hide-sm { display: none; } table { table-layout: fixed; } .cap { width: 26%; } .bar { min-width: 28px; } .name, .prov { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } .name { font-size: 12px; } .tag { display: none; } .unk { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } td { padding: 5px 4px; } th { padding: 3px 4px; } .pct { width: 32px; } .rank { width: 20px; } .role { width: 56px; } .pace { width: 84px; white-space: nowrap; overflow: hidden; } .word { display: none; } .narrow { display: inline; } }

